<script setup>
import { ref } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { useMovieStore } from '../stores/movie'
const username=ref('test'),password=ref('123456'),error=ref(''),loading=ref(false),store=useMovieStore(),router=useRouter(),route=useRoute()
async function submit(){error.value='';loading.value=true;try{await store.login(username.value.trim(),password.value);router.replace(String(route.query.redirect||'/'))}catch(e){error.value=e.message}finally{loading.value=false}}
</script>
<template><main class="login-page"><div class="orb orb-one"></div><div class="orb orb-two"></div><section class="login-intro"><div class="eyebrow">MOVIE RECOMMENDATION</div><h1>在万千光影中<br><em>遇见你的下一部电影</em></h1><p>基于用户评分与大数据分析，为每一次观影提供更懂你的选择。</p><div class="feature-line"><span>◉ 个性推荐</span><span>✦ 热门电影</span><span>★ 实时评分</span></div></section><form class="login-card" @submit.prevent="submit"><span class="login-logo">▶</span><h2>欢迎回来</h2><p>登录后开启专属观影旅程</p><label>用户名<input v-model="username" autocomplete="username" placeholder="请输入用户名" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" placeholder="请输入密码" required></label><div v-if="error" class="form-error">{{error}}</div><button class="primary-button full" :disabled="loading">{{loading?'正在登录…':'登 录'}}<span v-if="!loading">→</span></button><small>演示账号：test / 123456</small></form></main></template>
